CREATE FUNCTION public.admin_create_nft_task(_title text,_description text,_nft uuid,_quantity integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admins only'; END IF; IF length(trim(_title)) NOT BETWEEN 1 AND 120 OR length(trim(_description)) NOT BETWEEN 1 AND 4000 OR _quantity IS NULL OR _quantity NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid task'; END IF; IF NOT EXISTS(SELECT 1 FROM public.nfts WHERE id=_nft AND active AND mining_plan_id IS NULL) THEN RAISE EXCEPTION 'Choose a non-mining NFT'; END IF; INSERT INTO public.nft_tasks(title,description,nft_id,award_quantity) VALUES(trim(_title),trim(_description),_nft,_quantity) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.admin_set_task_reward(_rate numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admins only'; END IF; IF _rate IS NULL OR _rate<0 OR _rate>1000000 THEN RAISE EXCEPTION 'Invalid reward rate'; END IF; UPDATE public.settings SET task_sale_mvg_per_five_usd=_rate WHERE id=1; END $$;
CREATE FUNCTION public.admin_toggle_nft_task(_id uuid,_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admins only'; END IF; UPDATE public.nft_tasks SET active=_active WHERE id=_id; END $$;
CREATE FUNCTION public.submit_nft_task(_task uuid,_evidence text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF length(trim(_evidence)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Add completion evidence'; END IF; IF NOT EXISTS(SELECT 1 FROM public.nft_tasks WHERE id=_task AND active) THEN RAISE EXCEPTION 'Task unavailable'; END IF; INSERT INTO public.nft_task_submissions(task_id,user_id,evidence) VALUES(_task,auth.uid(),trim(_evidence)) ON CONFLICT(task_id,user_id) DO UPDATE SET evidence=EXCLUDED.evidence,status='pending',review_note=NULL,reviewed_at=NULL,reviewed_by=NULL WHERE nft_task_submissions.status='rejected' RETURNING id INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Task already submitted or awarded'; END IF; RETURN result; END $$;
CREATE FUNCTION public.review_nft_task(_id uuid,_approve boolean,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; t record; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admins only'; END IF; SELECT * INTO s FROM public.nft_task_submissions WHERE id=_id FOR UPDATE; IF s.id IS NULL OR s.status<>'pending' THEN RAISE EXCEPTION 'No pending submission'; END IF; SELECT * INTO t FROM public.nft_tasks WHERE id=s.task_id; IF _approve THEN IF NOT EXISTS(SELECT 1 FROM public.nfts WHERE id=t.nft_id AND active AND mining_plan_id IS NULL) THEN RAISE EXCEPTION 'Reward NFT unavailable'; END IF; INSERT INTO public.task_nft_instances(nft_id,submission_id,user_id) SELECT t.nft_id,s.id,s.user_id FROM generate_series(1,t.award_quantity); END IF; UPDATE public.nft_task_submissions SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,review_note=left(_note,2000),reviewed_by=auth.uid(),reviewed_at=now() WHERE id=s.id; INSERT INTO public.notifications(user_id,title,body) VALUES(s.user_id,CASE WHEN _approve THEN 'Task NFTs awarded' ELSE 'Task needs changes' END,CASE WHEN _approve THEN t.award_quantity||' NFT(s) added to your task collection.' ELSE left(_note,2000) END); END $$;
CREATE FUNCTION public.task_nft_market_action(_action text,_id uuid,_price numeric DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o record; l record; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND marketplace_blocked) THEN RAISE EXCEPTION 'Marketplace access suspended'; END IF; IF _action='list' THEN SELECT * INTO o FROM public.task_nft_instances WHERE id=_id AND user_id=auth.uid() FOR UPDATE; IF o.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.nfts WHERE id=o.nft_id AND active AND mining_plan_id IS NULL) THEN RAISE EXCEPTION 'NFT unavailable'; END IF; IF _price IS NULL OR _price<0.01 OR _price>100000 THEN RAISE EXCEPTION 'Enter a price between $0.01 and $100,000'; END IF; INSERT INTO public.task_nft_listings(instance_id,nft_id,seller_id,price_usd) VALUES(o.id,o.nft_id,auth.uid(),round(_price,2)) RETURNING id INTO result; RETURN result; ELSIF _action='cancel' THEN SELECT * INTO l FROM public.task_nft_listings WHERE id=_id AND seller_id=auth.uid() AND status='open' FOR UPDATE; IF l.id IS NULL THEN RAISE EXCEPTION 'Listing unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.task_nft_orders WHERE listing_id=l.id AND status='pending' AND expires_at>now()) THEN RAISE EXCEPTION 'A buyer has reserved this NFT; retry after checkout expires'; END IF; UPDATE public.task_nft_listings SET status='cancelled' WHERE id=l.id; RETURN l.id; END IF; RAISE EXCEPTION 'Invalid action'; END $$;
REVOKE ALL ON FUNCTION public.admin_create_nft_task(text,text,uuid,integer),public.admin_set_task_reward(numeric),public.admin_toggle_nft_task(uuid,boolean),public.submit_nft_task(uuid,text),public.review_nft_task(uuid,boolean,text),public.task_nft_market_action(text,uuid,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_create_nft_task(text,text,uuid,integer),public.admin_set_task_reward(numeric),public.admin_toggle_nft_task(uuid,boolean),public.submit_nft_task(uuid,text),public.review_nft_task(uuid,boolean,text),public.task_nft_market_action(text,uuid,numeric) TO authenticated;